import json, time, urllib.request, urllib.error
from datetime import datetime, timezone

BASE = "http://localhost:8080"
LOG = []

def req(path, method="GET", token=None):
    headers = {}
    if token:
        headers["Authorization"] = f"Bearer {token}"
    r = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(r, timeout=30) as resp:
            return resp.status, dict(resp.headers), resp.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read().decode(errors="replace")

class Client:
    def __init__(self):
        self.token = None
        self.new_token()

    def new_token(self):
        for attempt in range(20):
            st, h, body = req("/token", "POST")
            if st == 200:
                self.token = json.loads(body)["token"]
                return
            LOG.append(("token", st, body[:200]))
            time.sleep(min(2 ** attempt, 30))
        raise RuntimeError("could not get token")

    def get(self, path):
        # retries until success or 404; refreshes token on 401, waits on 429/5xx
        for attempt in range(200):
            st, h, body = req(path, token=self.token)
            if st == 200:
                return json.loads(body)
            if st == 404:
                return None
            LOG.append((path, st, body[:200], h.get("Retry-After")))
            if st == 401 or st == 403:
                self.new_token()
            elif st == 429 or st >= 500:
                ra = h.get("Retry-After")
                try:
                    wait = float(ra) if ra is not None else 2.0
                except ValueError:
                    wait = 2.0
                time.sleep(wait + 0.1)
            else:
                time.sleep(1)
        raise RuntimeError(f"gave up on {path}")

c = Client()

# Fetch all order pages, following total_pages and also checking next
orders = []
page = 1
total_pages = None
while True:
    data = c.get(f"/orders?page={page}")
    orders.extend(data["items"])
    total_pages = data["total_pages"]
    if page >= total_pages:
        break
    page += 1

print("pages fetched:", page, "total_pages:", total_pages, "raw items:", len(orders))

# Dedup by id, counting repeats
seen = {}
duplicates_skipped = 0
for o in orders:
    if o["id"] in seen:
        duplicates_skipped += 1
        if seen[o["id"]] != o:
            print("WARNING: differing duplicate", o["id"], seen[o["id"]], o)
    else:
        seen[o["id"]] = o

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive

statuses = {}
qualifying = []
for o in seen.values():
    statuses[o["status"]] = statuses.get(o["status"], 0) + 1
    if o["status"] != "shipped":
        continue
    t = datetime.fromisoformat(o["placed_at"]).astimezone(timezone.utc)
    if start <= t < end:
        qualifying.append(o)

print("distinct orders:", len(seen), "status counts:", statuses)
print("qualifying:", len(qualifying))

# Customer cache
cust_cache = {}
def customer(cid):
    if cid not in cust_cache:
        cust_cache[cid] = c.get(f"/customers/{cid}")
    return cust_cache[cid]

total = 0
by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
missing = []
for o in qualifying:
    cu = customer(o["customer_id"])
    if cu is None:
        missing.append(o["id"])
        continue
    pct = cu["discount_pct"]
    num = o["amount_cents"] * (100 - pct)
    # half-up rounding to whole cent, integer arithmetic (amounts non-negative)
    disc = (num + 50) // 100
    total += disc
    by_region[cu["region"]] += disc

print("customers cached:", len(cust_cache), "missing customers:", missing)

result = {
    "total_cents": total,
    "order_count": len(qualifying) - len(missing),
    "duplicates_skipped": duplicates_skipped,
    "by_region": by_region,
}
assert sum(by_region.values()) == total
with open("/workspace/result.json", "w") as f:
    json.dump(result, f, indent=2)
    f.write("\n")
print(json.dumps(result, indent=2))
print("log entries (errors/retries):", len(LOG))
for entry in LOG[:20]:
    print(entry)
EOF
cd /tmp/recon && time python3 -I compute.py

